def _calculate_total(order):
    total = 0
    for item in order["items"]:
        total += item["price"] * item["qty"]
    if total > 100:
        total *= 0.9
    if order.get("member"):
        total *= 0.95
    return total

def calc(o):
    """Calculate the total for an order with discounts."""
    try:
        return round(_calculate_total(o), 2)
    except:
        return 0

